<script>
document.querySelectorAll('[data-array-field]').forEach(input=>{const hidden=document.createElement('input');hidden.type='hidden';hidden.name=input.dataset.arrayField+'[]';input.insertAdjacentElement('afterend',hidden);const form=input.closest('form');form.addEventListener('submit',()=>{input.value.split(',').map(x=>x.trim()).filter(Boolean).forEach(v=>{const clone=hidden.cloneNode();clone.value=v;input.after(clone)});hidden.disabled=true;});});
document.querySelectorAll('select[multiple]').forEach(select=>{let input=document.querySelector('[data-search-for="'+select.id+'"]');if(!input){input=document.createElement('input');input.type='search';input.placeholder='Rechercher';input.setAttribute('aria-label','Rechercher dans '+select.id);select.insertAdjacentElement('beforebegin',input);}input.addEventListener('input',()=>{const query=input.value.toLocaleLowerCase();Array.from(select.options).forEach(option=>option.hidden=!option.text.toLocaleLowerCase().includes(query));});});
document.getElementById('image')?.addEventListener('change',event=>{const file=event.target.files[0],preview=document.getElementById('image-preview');if(file){preview.src=URL.createObjectURL(file);preview.hidden=false}else preview.hidden=true;});
document.querySelectorAll('.place-form details').forEach(details=>{const summary=details.querySelector('summary');if(summary){summary.setAttribute('aria-expanded',details.open?'true':'false');details.addEventListener('toggle',()=>summary.setAttribute('aria-expanded',details.open?'true':'false'));}});
document.querySelector('.place-form')?.addEventListener('submit',event=>{const input=document.querySelector('[name="points_text"]');if(input){input.remove();input.value.split('\n').filter(Boolean).forEach((line,i)=>{const [name,...description]=line.split('|');[['points['+i+'][name]',name.trim()],['points['+i+'][description]',description.join('|').trim()]].forEach(([key,value])=>{const hidden=document.createElement('input');hidden.type='hidden';hidden.name=key;hidden.value=value;event.currentTarget.appendChild(hidden)});});}});
</script>
